WITH recent_inventory AS (SELECT *, COALESCE(quantity, 0) AS quantity_filled FROM inventory WHERE quantity BETWEEN 138 AND 140), summary AS (SELECT product_id, MAX(quantity) - MIN(quantity) AS quantity_range, MAX(quantity) AS max_quantity FROM recent_inventory GROUP BY product_id) SELECT product_id, quantity_range, max_quantity FROM summary ORDER BY max_quantity DESC, product_id DESC LIMIT 50
